    function EnableGloomreedSpawn()

        if not (TimerGetTimeout(GloomreedTimer) > 0) then
            TimerStart(GloomreedTimer, 360., true, function()

                for i = 1, #GloomreedLocations do
                    local count = 0

                        EnumItemsInRect(GloomreedLocations[i], nil, function()
