                    ChangeJournalEntryObjective(player, "infected_quest_journal", "infected_quest_journal_gloomreed_count", GetLocalString("Мрачный тростник собран: ", "Gloomreed gathered: ") .. GloomreedGathered[player] .."/10", GloomreedGathered[player] < 10)
